{vCTEQuery}
{notInOpening}
Select FA_SET_AssetType.AssetTypeName ,CONVERt(Date,@FromDate,8)as fromdate ,CONVERt(Date,@ToDate,8) as ToDate ,Isnull(FA_AssetInformation.TagPrefix,'') + ' ' + FA_AssetInformation.TagNumber as tagNumber ,FA_AssetInformation.ItemID ,INV_Item.Description as ItemName ,FA_AssetInformation.StockGRNDate ,FA_AssetInformation.Rate as AsAtCost ,FA_AssetInformation.DepreciationRate ,0 as Addition ,FA_DepreciationProcess.WDV --,ISnull(FA_AssetInformation.CurrentValue,0) as CurrentDepreciation ,CONVERT(varchar,FA_Set_AssetLife.IntervalValue) + '-' + CONVERT(varchar,FA_Set_AssetLife.PeriodType) as PeriodName --,Case When FA_DepreciationProcess.DepreciatedFrom > SET_Period.StartDate Then FA_DepreciationProcess.DepreciationAmount Else 0 End As AsAtDepreciation ,isnull((Select SUM(FAI.OpeningDepreciation) from FA_AssetInformation FAI where FAI.Status = 1 AND FAI.TagPrefix=FA_AssetInformation.TagPrefix and FAI.TagNumber=FA_AssetInformation.TagNumber ),0) + isnull((Select SUM(FADP.DepreciationAmount) from FA_DepreciationProcess FADP INNER JOIN FA_AssetInformation FAI ON FADP.AssetIdentityID = FAI.AssetInfoID and FADP.CompanyID= FAI.CompanyID AND FADP.Status = 1 AND FAI.Status = 1 where FAI.TagPrefix=FA_AssetInformation.TagPrefix and FAI.TagNumber=FA_AssetInformation.TagNumber AND ( CAST( FADP.DepreciatedFrom AS Date) >= SET_Period.StartDate ) and CAST( FADP.DepreciatedFrom AS Date) < @FromDate ),0) AS AsAtDepreciation ,FA_AssetInformation.LastDepreciationDate ,SET_Period.Description ,FA_DepreciationProcess.DepreciatedFrom --,(Case when (select Count(FADP.DepreciationAmount) -- from FA_DepreciationProcess FADP -- INNER JOIN FA_AssetInformation FAI ON FADP.AssetIdentityID = FAI.AssetInfoID -- and FADP.CompanyID= FAI.CompanyID -- where FAI.TagPrefix=FA_AssetInformation.TagPrefix and FAI.TagNumber=FA_AssetInformation.TagNumber -- and FA_DepreciationProcess.AssetIdentityID=FADP.AssetIdentityID -- AND CAST( FADP.DepreciatedFrom AS Date) not between SET_Period.StartDate and FA_DepreciationProcess.DepreciatedFrom)> 0 -- then FA_DepreciationProcess.DepreciationAmount -- else 0 END) AS DepreciationAmount ,ISnull(FA_DepreciationProcess.DepreciationAmount,0) as DepreciationAmount ,isnull((Case when FA_AssetInformation.LastDepreciationDate = FA_DepreciationProcess.DepreciatedUpTo then FA_AssetInformation.isdisposed else 0 end),0) isdisposed ,isnull(FA_AssetInformation.ParentAssetInfoID,FA_AssetInformation.AssetInfoID)ParentAssetInfoID ,isnull(FA_AssetInformation.IsChild,0)IsChild, --set_costcenter.CostCenterName (select scc.CostCenterName from SET_CostCenter scc where scc.CostCenterID = SET_CostCenter.BSCostCenterID) CostCenterName from FA_AssetInformation INNER JOIN INV_Item ON INV_Item.ItemID = FA_AssetInformation.ItemID --AND INV_Item.CompanyID=FA_AssetInformation.CompanyID
Left JOIN INV_StockTransactionDetail on FA_AssetInformation.ItemID = INV_StockTransactionDetail.ItemID AND INV_StockTransactionDetail.TransactionDetailID = FA_AssetInformation.StockDetailID AND INV_StockTransactionDetail.StockTransactionID = FA_AssetInformation.StockHeaderID AND INV_StockTransactionDetail.CompanyID = FA_AssetInformation.CompanyID
INNER JOIN FA_SET_AssetType ON FA_SET_AssetType.AssetTypeID = FA_AssetInformation.AssetTypeID AND FA_SET_AssetType.CompanyID = FA_AssetInformation.CompanyID AND FA_SET_AssetType.Status = 1 INNER JOIn SET_Company ON FA_AssetInformation.CompanyID=SET_Company.CompanyId AND SET_Company.Status=1 INNER JOIN SET_CompanyPeriod ON SET_CompanyPeriod.CompanyID=SET_Company.CompanyId AND SET_CompanyPeriod.status=1 INNER JOIN SET_Period on SET_Period.PeriodID = SET_CompanyPeriod.PeriodID inner JOIN FA_DepreciationProcess ON FA_DepreciationProcess.AssetIdentityID = FA_AssetInformation.AssetInfoID AND FA_SET_AssetType.CompanyID = FA_DepreciationProcess.CompanyID AND FA_DepreciationProcess.Status = 1 INNER JOIN FA_Set_AssetLife ON FA_Set_AssetLife.AssetLifeID = FA_AssetInformation.ExpectedLifeID AND FA_Set_AssetLife.CompanyID = FA_AssetInformation.CompanyID AND FA_Set_AssetLife.Status = 1 left join set_costcenter on set_costcenter.costcenterid = FA_AssetInformation.CostCenterID WHERE FA_AssetInformation.CompanyID = @CompanyID And (FA_DepreciationProcess.DepreciatedFrom between @FromDate AND @ToDate Or FA_DepreciationProcess.DepreciatedUpTo between @FromDate AND @ToDate) and FA_AssetInformation.opening is null {0} GROUP BY FA_AssetInformation.TagPrefix, FA_AssetInformation.TagNumber ,FA_AssetInformation.ItemID ,INV_Item.Description ,FA_AssetInformation.AssetInfoID ,FA_Set_AssetLife.IntervalValue ,FA_Set_AssetLife.PeriodType ,FA_DepreciationProcess.DepreciatedFrom ,FA_DepreciationProcess.WDV ,FA_AssetInformation.Rate ,FA_AssetInformation.StockGRNDate ,FA_AssetInformation.DepreciationRate ,FA_DepreciationProcess.PeriodStatusID ,FA_SET_AssetType.AssetTypeName ,FA_AssetInformation.LastDepreciationDate ,FA_AssetInformation.WrittenDownValue ,FA_DepreciationProcess.DepreciationAmount ,FA_DepreciationProcess.AssetIdentityID ,FA_AssetInformation.AssetInfoID ,FA_DepreciationProcess.DepreciatedUpto ,FA_AssetInformation.CurrentValue ,SET_Period.StartDate ,SET_Period.Description ,FA_AssetInformation.isdisposed ,FA_AssetInformation.ParentAssetInfoID ,FA_AssetInformation.IsChild ,set_costcenter.CostCenterName ,SET_CostCenter.BSCostCenterID --ORDER BY FA_AssetInformation.ItemID
{Query_Add_Purchase}

{vCTEQuery}
{notInOpening}
Select FA_SET_AssetType.AssetTypeName ,CONVERt(Date,@FromDate,8)as fromdate ,CONVERt(Date,@ToDate,8) as ToDate ,Isnull(FA_AssetInformation.TagPrefix,'') + ' ' + FA_AssetInformation.TagNumber as tagNumber ,FA_AssetInformation.ItemID ,INV_Item.Description as ItemName ,FA_AssetInformation.StockGRNDate ,(Case when (select count(FAI.WrittenDownValue) from FA_AssetInformation FAI INNER JOIN FA_DepreciationProcess FADP ON FADP.AssetIdentityID = FAI.AssetInfoID where FAI.TagPrefix=FA_AssetInformation.TagPrefix and FAI.TagNumber=FA_AssetInformation.TagNumber AND CAST( FADP.DepreciatedFrom AS Date) > SET_Period.StartDate and CAST( FADP.DepreciatedFrom AS Date) < FA_DepreciationProcess.DepreciatedFrom)> 0 then FA_AssetInformation.WrittenDownValue else 0 END) AS AsAtCost ,FA_AssetInformation.DepreciationRate ,(Case when (Select count(FAI.WrittenDownValue) as Addition from FA_AssetInformation FAI INNER JOIN FA_DepreciationProcess FADP ON FADP.AssetIdentityID = FAI.AssetInfoID where FAI.TagPrefix=FA_AssetInformation.TagPrefix and FAI.TagNumber=FA_AssetInformation.TagNumber and CAST(FADP.DepreciatedFrom AS Date) > SET_Period.StartDate and CAST( FADP.DepreciatedFrom AS Date) < FA_DepreciationProcess.DepreciatedFrom ) > 0 then 0 else isnull(FA_AssetInformation.WrittenDownValue,0) end ) as Addition ,FA_DepreciationProcess.WDV --,ISnull(FA_AssetInformation.CurrentValue,0) as CurrentDepreciation ,case FA_DepreciationProcess.PeriodStatusID when 1 then 'Day' when 2 then 'Month' when 3 then 'Quarter' when 4 then 'Year' end as PeriodName --,Case When FA_DepreciationProcess.DepreciatedFrom > SET_Period.StartDate Then FA_DepreciationProcess.DepreciationAmount Else 0 End As AsAtDepreciation ,(isnull((Select SUM(FADP.DepreciationAmount) from FA_DepreciationProcess FADP INNER JOIN FA_AssetInformation FAI ON FADP.AssetIdentityID = FAI.AssetInfoID and FADP.CompanyID= FAI.CompanyID where FAI.TagPrefix=FA_AssetInformation.TagPrefix and FAI.TagNumber=FA_AssetInformation.TagNumber AND ( CAST( FADP.DepreciatedFrom AS Date) >= SET_Period.StartDate ) and CAST( FADP.DepreciatedFrom AS Date) < FA_DepreciationProcess.DepreciatedFrom ),0) + ISNULL(FA_AssetInformation.OpeningDepreciation,0)) AS AsAtDepreciation ,FA_AssetInformation.LastDepreciationDate ,SET_Period.Description ,FA_DepreciationProcess.DepreciatedFrom --,(Case when (select Count(FADP.DepreciationAmount) -- from FA_DepreciationProcess FADP -- INNER JOIN FA_AssetInformation FAI ON FADP.AssetIdentityID = FAI.AssetInfoID -- and FADP.CompanyID= FAI.CompanyID -- where FAI.TagPrefix=FA_AssetInformation.TagPrefix and FAI.TagNumber=FA_AssetInformation.TagNumber -- and FA_DepreciationProcess.AssetIdentityID=FADP.AssetIdentityID -- AND CAST( FADP.DepreciatedFrom AS Date) not between SET_Period.StartDate and FA_DepreciationProcess.DepreciatedFrom)> 0 -- then FA_DepreciationProcess.DepreciationAmount -- else 0 END) AS DepreciationAmount ,ISnull(FA_DepreciationProcess.DepreciationAmount,0) as DepreciationAmount ,isnull((Case when FA_AssetInformation.LastDepreciationDate = FA_DepreciationProcess.DepreciatedUpTo then FA_AssetInformation.isdisposed else 0 end),0) isdisposed ,isnull(FA_AssetInformation.ParentAssetInfoID,FA_AssetInformation.AssetInfoID)ParentAssetInfoID ,isnull(FA_AssetInformation.IsChild,0)IsChild, --set_costcenter.CostCenterName set_costcenter.CostCenterName as CostCenterName, SET_Location.LocationName from FA_AssetInformation INNER JOIN INV_Item ON INV_Item.ItemID = FA_AssetInformation.ItemID --AND INV_Item.CompanyID=FA_AssetInformation.CompanyID
Left JOIN INV_StockTransactionDetail on FA_AssetInformation.ItemID = INV_StockTransactionDetail.ItemID AND INV_StockTransactionDetail.TransactionDetailID = FA_AssetInformation.StockDetailID AND INV_StockTransactionDetail.StockTransactionID = FA_AssetInformation.StockHeaderID AND INV_StockTransactionDetail.CompanyID = FA_AssetInformation.CompanyID
INNER JOIN FA_SET_AssetType ON FA_SET_AssetType.AssetTypeID = FA_AssetInformation.AssetTypeID AND FA_SET_AssetType.CompanyID = FA_AssetInformation.CompanyID AND FA_SET_AssetType.Status = 1 INNER JOIn SET_Company ON FA_AssetInformation.CompanyID=SET_Company.CompanyId AND SET_Company.Status=1 INNER JOIN SET_CompanyPeriod ON SET_CompanyPeriod.CompanyID=SET_Company.CompanyId AND SET_CompanyPeriod.status=1 INNER JOIN SET_Period on SET_Period.PeriodID = SET_CompanyPeriod.PeriodID inner JOIN FA_DepreciationProcess ON FA_DepreciationProcess.AssetIdentityID = FA_AssetInformation.AssetInfoID AND FA_SET_AssetType.CompanyID = FA_DepreciationProcess.CompanyID AND FA_DepreciationProcess.Status = 1 left join set_costcenter on set_costcenter.costcenterid = FA_AssetInformation.CostCenterID left join SET_Location on SET_Location.LocationID = FA_DepreciationProcess.LocationID WHERE FA_AssetInformation.CompanyID = @CompanyID And (FA_DepreciationProcess.DepreciatedFrom between @FromDate AND @ToDate Or FA_DepreciationProcess.DepreciatedUpTo between @FromDate AND @ToDate) and FA_AssetInformation.opening is null {0} GROUP BY FA_AssetInformation.TagPrefix, FA_AssetInformation.TagNumber ,FA_AssetInformation.ItemID ,INV_Item.Description ,FA_AssetInformation.AssetInfoID ,FA_DepreciationProcess.DepreciatedFrom ,FA_DepreciationProcess.WDV ,FA_AssetInformation.Rate ,FA_AssetInformation.StockGRNDate ,FA_AssetInformation.DepreciationRate ,FA_DepreciationProcess.PeriodStatusID ,FA_SET_AssetType.AssetTypeName ,FA_AssetInformation.LastDepreciationDate ,FA_AssetInformation.WrittenDownValue ,FA_AssetInformation.OpeningDepreciation ,FA_DepreciationProcess.DepreciationAmount ,FA_DepreciationProcess.AssetIdentityID ,FA_AssetInformation.AssetInfoID ,FA_DepreciationProcess.DepreciatedUpto ,FA_AssetInformation.CurrentValue ,SET_Period.StartDate ,SET_Period.Description ,FA_AssetInformation.isdisposed ,FA_AssetInformation.ParentAssetInfoID ,FA_AssetInformation.IsChild ,set_costcenter.CostCenterName ,SET_CostCenter.BSCostCenterID ,SET_Location.LocationName --ORDER BY FA_AssetInformation.ItemID
{Query_Add_Purchase}
